// Bounded source-component replay. All mutation callbacks are inert memory only.
const assert=require('node:assert/strict'),fs=require('node:fs'),http=require('node:http'),os=require('node:os'),path=require('node:path');
const{spawnSync}=require('node:child_process'),{chromium}=require('playwright-core');
const repo=path.resolve(__dirname,'../..'),output=fs.mkdtempSync(path.join(os.tmpdir(),'nekodex-basic-drafts-'));
const evidence=process.env.NEKODEX_DRAFT_EVIDENCE;let server,browser;const result={checks:[],pageErrors:[],realProviderCalls:0,started:new Date().toISOString()};
function check(name){result.checks.push(name)}
async function main(){try{
 const build=spawnSync('bun',['build','tests/fixtures/basic-conversation-drafts-ui.tsx','--target=browser','--outdir='+output],{cwd:repo,encoding:'utf8',timeout:20000});assert.equal(build.status,0,build.stderr);
 server=http.createServer((req,res)=>{const file=req.url.split('?')[0];if(file==='/'){res.setHeader('Content-Type','text/html');res.end('<!doctype html><html lang="en" data-theme="dark"><meta charset="UTF-8"><link rel="stylesheet" href="/basic-conversation-drafts-ui.css"><style>body{font-family:system-ui;background:var(--bg-under);color:var(--text-primary);padding:20px}*{box-sizing:border-box}</style><div id="root"></div><script type="module" src="/basic-conversation-drafts-ui.js"></script></html>');return}if(!/^\/basic-conversation-drafts-ui\.(css|js)$/.test(file)){res.writeHead(404);res.end();return}res.setHeader('Content-Type',file.endsWith('css')?'text/css':'text/javascript');res.end(fs.readFileSync(path.join(output,file.slice(1))))});
 await new Promise(resolve=>server.listen(Number(process.env.NEKODEX_DRAFT_PORT)||0,'127.0.0.1',resolve));result.url='http://127.0.0.1:'+server.address().port;result.serverPid=process.pid;
 if(process.argv.includes('--serve')){console.log(result.url);await new Promise(resolve=>{process.once('SIGTERM',resolve);process.once('SIGINT',resolve)});return}
 browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:1000,height:850}});page.setDefaultTimeout(5000);page.on('pageerror',e=>result.pageErrors.push(e.message));
 await page.goto(result.url);const input=page.getByLabel('Native message'),a=page.getByRole('button',{name:/Conversation A/}),b=page.getByRole('button',{name:/Conversation B/}),fresh=page.getByRole('button',{name:'New conversation',exact:true});await input.waitFor();await input.fill('New compose draft');await a.click();await input.fill('Draft A');await b.click();await input.fill('Draft B');await a.click();assert.equal(await input.inputValue(),'Draft A');await a.click();assert.equal(await input.inputValue(),'Draft A');await fresh.click();assert.equal(await input.inputValue(),'New compose draft');await b.click();assert.equal(await input.inputValue(),'Draft B');check('A/B/New/reselect drafts preserved');
 await page.getByRole('button',{name:'Clear draft',exact:true}).click();assert.equal(await input.inputValue(),'');await a.click();assert.equal(await input.inputValue(),'Draft A');check('Explicit clear affects current draft only');
 const priorEpoch=await page.evaluate(()=>window.basicDraftFixture.snapshot.epoch);await page.evaluate(()=>{window.basicDraftFixture.snapshot.epoch='0199a001-0000-7000-8000-000000000009'});await page.getByRole('button',{name:'Refresh conversations',exact:true}).click();await page.waitForFunction(()=>document.querySelector('textarea.native-persistent__prompt')?.value==='');await input.fill('Different account epoch draft');await page.evaluate(epoch=>{window.basicDraftFixture.snapshot.epoch=epoch},priorEpoch);await page.getByRole('button',{name:'Refresh conversations',exact:true}).click();await page.waitForFunction(()=>document.querySelector('textarea.native-persistent__prompt')?.value==='Draft A');assert.equal(await input.inputValue(),'Draft A');check('Account epoch separates drafts without erasing earlier scope');
 await page.getByRole('button',{name:'Continue conversation',exact:true}).click();await fresh.click();await page.evaluate(()=>window.basicDraftFixture.resolveNative());await page.waitForFunction(()=>!window.basicDraftFixture.nativePending);await a.click();await page.getByText('INERT COMPLETED',{exact:true}).waitFor();assert.equal(await input.inputValue(),'');await fresh.click();assert.equal(await input.inputValue(),'New compose draft');check('Late send completion clears submitted source only');
 await page.getByRole('checkbox',{name:'Retain this new conversation’s messages and context locally for continuation and forks.',exact:true}).check();await page.getByRole('button',{name:'Create and send',exact:true}).click();await page.evaluate(()=>window.basicDraftFixture.resolveNative(true));await page.getByText('INERT THREAD — NO TURN SENT',{exact:true}).waitFor();assert.equal(await input.inputValue(),'New compose draft');check('Created thread whose first turn was not sent retains draft');

 if(evidence)await page.screenshot({path:path.join(evidence,'native-drafts.png'),fullPage:true});
 await a.click();await input.fill('Inert turn to stop');await page.getByRole('button',{name:'Continue conversation',exact:true}).click();
 const stop=page.getByRole('button',{name:'Stop Native turn',exact:true});await stop.waitFor();assert.equal(await stop.isEnabled(),true);check('Stop appears after passive ACK read without manual refresh and bypasses pending Send');
 await stop.click();await page.waitForFunction(()=>!!window.basicDraftFixture.stopPending);assert.equal(await page.getByRole('button',{name:'Stopping Native turn…',exact:true}).isEnabled(),false);assert.equal(await page.getByText('Stop requested; waiting for the turn to settle.',{exact:true}).isVisible(),true);check('Stop ACK remains pending rather than reporting stopped');
 await page.evaluate(()=>window.basicDraftFixture.resolveStop());await page.getByRole('button',{name:'Continue conversation',exact:true}).waitFor();await page.waitForFunction(()=>!window.basicDraftFixture.stopPending&&!window.basicDraftFixture.nativePending);await page.getByRole('button',{name:'Clear draft',exact:true}).click();const reads=await page.evaluate(()=>window.basicDraftFixture.calls.filter(c=>c.action==='snapshot').length);await page.waitForTimeout(1200);assert.equal(await page.evaluate(()=>window.basicDraftFixture.calls.filter(c=>c.action==='snapshot').length),reads);check('Exact Stop settlement retires pending state and passive refresh');
 await page.getByRole('button',{name:'Archive locally',exact:true}).click();await page.getByRole('dialog').waitFor();await page.getByRole('dialog').getByRole('button',{name:'Cancel',exact:true}).click();assert.equal(await a.isVisible(),true);check('Archive confirmation cancel preserves active record');
 await page.getByRole('button',{name:'Archive locally',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Confirm local archive',exact:true}).click();await page.waitForFunction(()=>!!window.basicDraftFixture.nativePending);await page.evaluate(()=>window.basicDraftFixture.resolveNative());await page.getByRole('dialog').waitFor({state:'hidden'});assert.equal(await a.count(),0);await page.locator('summary').filter({hasText:'Local archive'}).click();await page.getByRole('heading',{name:/Conversation A/}).waitFor();check('Archived record leaves active list and remains viewable in local archive');
 await page.evaluate(()=>{const f=window.basicDraftFixture;f.snapshot.conversations.push({...f.snapshot.archivedConversations[0],status:'idle',ownerAvailable:true});f.snapshot.archivedConversationIds=[]});await page.getByRole('button',{name:'Refresh conversations',exact:true}).click();await page.waitForFunction(()=>window.basicDraftFixture.calls.at(-1).action==='snapshot');assert.equal(await a.count(),0);check('Late active snapshot cannot resurrect an archived tombstone');if(evidence)await page.screenshot({path:path.join(evidence,'native-archive.png'),fullPage:true});

 await page.goto(result.url+'/?family=history');const label=page.getByRole('textbox',{name:'Task / thread label',exact:true}),text=page.getByRole('textbox',{name:'Selected text',exact:true}),checked=page.getByRole('checkbox',{name:/I checked this selection/});await label.fill('inert selection');await text.fill('Original selected text');await checked.check();await page.getByRole('button',{name:'Save selection',exact:true}).click();await page.waitForFunction(()=>!!window.basicDraftFixture.historyPending);for(const locator of[label,text,checked,page.getByRole('combobox',{name:'Message role',exact:true}),page.getByRole('combobox',{name:'Actual author',exact:true})])assert.equal(await locator.isDisabled(),true);check('All import controls freeze while original save pending');if(evidence)await page.screenshot({path:path.join(evidence,'history-pending.png'),fullPage:true});
 await page.evaluate(()=>window.basicDraftFixture.resolveHistory(true));await page.getByText('Inert save failed',{exact:true}).waitFor();assert.equal(await text.inputValue(),'Original selected text');assert.equal(await text.isEnabled(),true);check('Failed import restores editable retryable original draft');await page.getByRole('button',{name:'Save selection',exact:true}).click();await page.waitForFunction(()=>!!window.basicDraftFixture.historyPending);await page.evaluate(()=>window.basicDraftFixture.resolveHistory());await page.getByText('Selection saved.',{exact:true}).waitFor();assert.equal(await text.inputValue(),'');check('Successful import clears only frozen submitted text');
 result.realProviderCalls=await page.evaluate(()=>window.basicDraftFixture.realProviderCalls);assert.equal(result.realProviderCalls,0);assert.deepEqual(result.pageErrors,[]);check('No unhandled page errors or real provider calls');
 }finally{if(browser)await browser.close();if(server)await new Promise(resolve=>server.close(resolve));fs.rmSync(output,{recursive:true,force:true});result.browserClosed=true;result.serverClosed=true;result.finished=new Date().toISOString();if(evidence){fs.mkdirSync(evidence,{recursive:true});fs.writeFileSync(path.join(evidence,'draft-checks.json'),JSON.stringify(result,null,2))}console.log(JSON.stringify(result,null,2))}}
main().catch(e=>{console.error(e);process.exitCode=1});
